window.MONSTER_CHUNK_130 = [{"name":"Margoyle Gargoyle","cr":5,"xp":1600,"alignment":"CE","size":"Medium","type":"monstrous humanoid","subtypes":["earth"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":18,"ac_touch":12,"ac_flat_footed":16,"ac_mods":"+2 Dex, +6 natural","hp":63,"hd":"6d10+24 (+6)","hdvalue":6,"fort":6,"ref":7,"will":6,"dr":"10/magic","speed":[{"type":"land","speed":40},{"type":"fly","speed":60,"maneuverability":"average"}],"melee":"2 claws +9 (1d6+3), bite +9 (1d6+3), gore +9 (1d6+3)","space":"5 ft.","reach":"5 ft.","strength":17,"dexterity":15,"constitution":19,"intelligence":8,"wisdom":12,"charisma":8,"baseatk":6,"cmb":9,"cmd":21,"feats":[{"feat":"Power Attack"},{"feat":"Skill Focus (Fly)"},{"feat":"Toughness"}],"skills":[{"skill":"Fly","value":14},{"skill":"Perception","value":10},{"skill":"Stealth","value":10,"special":"+16 stony environs"},{"skill":"Survival","value":7}],"languages":["Common","Terran"],"sq":[{"type":"freeze"}],"environments":["any land","any aquatic","any underground"],"organizations":["solitary","pair","wing (1-2 margoyles and 4-6 gargoyles)"],"treasure":"standard","description_visual":"This creature looks like a hideously ugly humanoid chiseled of brown stone. Two large horns protrude from its head, just above its eyes. Four large stony spikes jut from its shoulder blades. Its hands and ft. end in sharpened claws.","group":"Gargoyle","source":"Tome of Horrors Complete (3pp)","description":"A margoyle is a slightly larger version of the standard gargoyle. It is meaner, eviler, and deadlier than the normal gargoyle. Margoyles are most often encountered in subterranean regions and often have a pack of gargoyles with them. In such cases, the margoyle is looked upon as the master or leader of the group.","ecology":"","habitat_society":"","credit":"The Margoyle originally appeared in the First Edition module S4 Lost Caverns of Tsojcanth (© TSR/Wizards of the Coast, 1982) and later in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission. It was called the \"Marlgoyle\" in S4 (note the extra \"l\")."},{"name":"Murder Crow","cr":5,"xp":1600,"alignment":"CE","size":"Medium","type":"undead","init":9,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":19,"ac_touch":16,"ac_flat_footed":13,"ac_mods":"+5 Dex, +1 dodge, +3 natural","hp":67,"hd":"9d8+27","hdvalue":9,"fort":5,"ref":8,"will":8,"immunities":["undead traits"],"speed":[{"type":"land","speed":10},{"type":"fly","speed":70,"maneuverability":"average"}],"melee":"2 claws +7 (1d4+1), 1 bite +7 (1d6+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"death throes"},{"type":"eye rake"}],"strength":12,"dexterity":20,"intelligence":2,"wisdom":14,"charisma":14,"baseatk":6,"cmb":7,"cmd":23,"feats":[{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Toughness"},{"feat":"Wingover"}],"skills":[{"skill":"Perception","value":10},{"skill":"Stealth","value":12}],"environments":["temperate forests"],"organizations":["solitary","gang (2-4)","murder (10-90)"],"treasure":"none","description_visual":"This creature appears to be a crow about 4 ft. tall. Its feathers are tattered, blood-soaked, and matted against its rotting form. A decaying stench emanates from it as it circles overhead.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Death Throes","kind":"Su","details":"If a murder crow is reduced to 0 hit points or less, it explodes into a murder of standard crows. Use the statistics for the undead raven swarm found elsewhere in this book. These smaller crows continue to relentlessly attack all living creatures within sight."},{"type":"Eye Rake","kind":"Ex","details":"If a murder crow hits an opponent with both claws in the same round, the victim must succeed on a DC 15 Reflex save or be blinded as the crow scratches and tears at the victim's eyes. The blindness last for 1d4 days while the eyes naturally heal, or until healed (with remove blindness or a successful DC 15 Heal check). The save DC is Charisma-based and includes a +1 racial bonus."}],"description":"Murder crows are undead avians found haunting cemeteries, graveyards, and charnel houses where they feast on the carcasses of humanoids, animals, and other once living creatures. These creatures are formed in desolate areas where the formless souls of birds condense into a solitary creature-a murder crow. Murder crows attack with their jagged beaks and sinister talons. Rarely does a murder crow face its adversaries on the ground, preferring instead to execute a flyby attack, enhancing this attack with its special eye rake ability.\n\nMurder crows resemble standard crows except that they stand nearly 4 ft. tall with a wingspan of 9 ft. Their tattered feathers are black and carry the stench of death. The eyes of a murder crow are bleak and hollow, showing no signs of emotion or life. Murder crows possess an intelligence level similar to that of their living counterparts; however, they have a great level of awareness that allows them to hunt and kill in a much more proficient manner.","ecology":"","habitat_society":""},{"name":"Neomimic","cr":5,"xp":1600,"alignment":"NE","size":"Medium","type":"aberration","init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":18,"ac_touch":12,"ac_flat_footed":16,"ac_mods":"+2 Dex, +6 natural","hp":52,"hd":"7d8+21","hdvalue":7,"fort":5,"ref":6,"will":7,"defensive_abilities":["amorphous"],"immunities":["acid"],"speed":[{"type":"land","speed":30}],"melee":"slam +10 (1d8+6 plus adhesive) or 2 slams (1d8+6 plus adhesive)","space":"5 ft.","reach":"5 ft.","strength":19,"dexterity":14,"constitution":17,"intelligence":13,"wisdom":15,"charisma":13,"baseatk":5,"cmb":9,"cmd":21,"feats":[{"feat":"Light Armor Proficiency","type":"bonus"},{"feat":"Medium Armor Proficiency","type":"bonus"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Martial Weapon Proficiency","type":"bonus"},{"feat":"Skill Focus (Stealth)"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Climb","value":14},{"skill":"Disguise","value":8},{"skill":"Intimidate","value":9},{"skill":"Knowledge (dungeoneering)","value":8},{"skill":"Perception","value":12},{"skill":"Stealth","value":13}],"languages":["Common"],"sq":[{"type":"change shape","details":"small, medium, or large creature; alter self, beast shape III, and plant shape I"}],"environments":["any land","any underground"],"organizations":["solitary"],"treasure":"none","description_visual":"This creature is grey-green blob of what appears to be human flesh. It shudders, and then begins growing arms and legs as it assumes a humanoid shape.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Adhesive","kind":"Ex","details":"A neomimic exudes a thick slime that acts as a powerful adhesive, holding fast any creatures or items that touch it. An adhesive-covered neomimic automatically grapples any creature it hits with its slam attack. Opponents so grappled cannot get free while the neomimic is alive without removing the adhesive first. A weapon that strikes an adhesive-coated neomimic is stuck fast unless the wielder succeeds on a DC 17 Reflex save. A successful DC 17 Strength check is needed to pry off a stuck weapon. Strong alcohol or universal solvent dissolves the adhesive, but the neomimic can still grapple normally. A neomimic can dissolve its adhesive at will, and the substance breaks down 5 rounds after the creature dies. The save DC is Strength-based."},{"type":"Alter Physique","kind":"Ex","details":"At will as a standard action, a neomimic can alter its physical structure to affect its physique. A neomimic can shift points between its Strength, Dexterity, or Constitution by reducing one or more of the scores while raising one or more by the same amount. The neomimic can shift no more than 12 points at one time and no score can be raised or lowered by more than 10 points. For example, a neomimic can reduce its Strength from 19 to 10 while increasing its Dexterity from 14 to 18. It could not, however, decrease its Strength to less than 9, or increase its Dexterity to greater than 24. These changes remain in effect until the neomimic uses this ability again."}],"description":"Unlike its lesser kin, the skin of a neomimic is soft and fleshy, and it cannot substantially alter its texture to appear as wood or stone. When taking the form of a creature of any kind, a neomimic cannot assume the form of a specific individual. Anyone who examines the neomimic can detect the ruse with a successful Perception check opposed by the neomimic's Disguise check.\n\nThe neomimic is thought by sages to be an advanced species of mimic perhaps from some distant future or unknown plane. Neomimics may also be somehow related to doppelgangers, but any such relationship has not been proven.\n\nIn its natural state, a neomimic is an amorphous blob of fleshy substance approximately 5 ft. across. Its skin is the color of dead tissue, a sickening grey-green hue tinged here and there with what appears to be healthy human skin. Like normal mimics, a neomimic can assume nearly any shape it can conceive. A neomimic often takes humanoid form, however, and rarely resorts to taking the shape of inanimate objects.\n\nA neomimic in its natural form is 6 ft. tall and weighs 200 pounds.\n\nIn its natural form or the form of an inanimate object, a neomimic pounds its opponent with powerful fist-shaped pseudopods in much the same way as a normal mimic. While in the form of a creature, however, a neomimic strives to fight as much as possible like the creature it is emulating.","ecology":"","habitat_society":""},{"name":"Night Adder Inphidian","cr":5,"xp":1600,"alignment":"NE","size":"Medium","type":"monstrous humanoid","subtypes":["reptilian"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+2 Dex, +4 natural","hp":45,"hd":"6d10+12","hdvalue":6,"fort":6,"ref":7,"will":7,"speed":[{"type":"land","speed":30}],"melee":"2 snake-hand bites +8 (1d4+1 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"poison","details":"DC 17"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":9,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"suggestion"}]},{"frequency":"3/day","spells":[{"spell":"cause fear"},{"spell":"darkness"},{"spell":"hypnotic pattern"}]}],"strength":12,"dexterity":15,"constitution":15,"intelligence":13,"wisdom":14,"charisma":14,"baseatk":6,"cmb":7,"cmd":19,"feats":[{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Craft (alchemy)","value":10},{"skill":"Knowledge (nature)","value":7},{"skill":"Knowledge (any one)","value":7},{"skill":"Perception","value":15},{"skill":"Stealth","value":15,"special":"+19 in shadow"}],"languages":["Aklo","Common","Inphidian"],"environments":["any underground","warm forests","warm plains"],"organizations":["solitary","troupe (1 night adder plus 2 cobrabacks and 1d6 common inphidians)"],"treasure":"standard","description_visual":"Dressed in black robes, this creature has black scales covering its entire body. Its head is serpentine and its arms end in snake-like hands resembling black mambas.","group":"Inphidian","source":"Tome of Horrors Complete (3pp)","description":"Night adders are nocturnal inphidians who often serve as assassin-priests, monks or sorcerers in an inphidian nest. They act as advisors, counselors, and magistrates to the rulers and leaders while simultaneously serving as healers, lorekeepers, and sages to the common inphidian populace. A night adder, much alike all inphidians, is a snake-like humanoid whose hands have been replaced with the head of a snake; in the case of a night adder, its snake-hands resemble a black mamba. Its body is black and its eyes are a pale rose. A night adder stands 6-1/2 ft. tall and weighs 190 pounds. Night adders attack with their multiple bites seeking to inflict as many venomous bites on a single foe as possible before moving on to the next target. Night adder clerics and sorcerers use area and ranged attack spells, then power up with defensive and offensive personal effect magic before entering melee.","as_character":[{"description":"","racial_traits":[{"type":"Ability Score Bonuses","value":"+2 Strength, +4 Dexterity, +4 Constitution, +2 Intelligence, +4 Wisdom, +4 Charisma."},{"type":"Racial Hit Dice","value":"A night adder inphidian begins with six levels of monstrous humanoid, which provide 6d10 Hit Dice, a base attack bonus of +6, and base saving throw bonuses of Fort +2, Ref +5, and Will +5."},{"type":"Racial Skills","value":"A night adder inphidian's monstrous humanoid levels give it skill points equal to 6 x (4 + Int modifier). It has a +4 racial bonus on Perception and Stealth checks, and an additional +4 to Stealth checks when in areas of shadow."},{"type":"Racial Feats","value":"A night adder inphidian's monstrous humanoid levels give it three feats."},{"type":"Special Attacks","value":"Poison and spell-like abilities."}]}],"ecology":"","habitat_society":""},{"name":"Niln","cr":5,"xp":1600,"alignment":"NE","size":"Medium","type":"outsider","subtypes":["air","extraplanar","water"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":14,"ac_flat_footed":11,"ac_mods":"+4 Dex, +1 natural","hp":55,"hd":"5d10+10","hdvalue":5,"fort":6,"ref":8,"will":4,"defensive_abilities":["elemental traits"],"dr":"5/-","speed":[{"type":"fly","speed":60,"maneuverability":"perfect"}],"melee":"slam +9 (2d6+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"drench"},{"type":"drowning fog"}],"strength":12,"dexterity":19,"constitution":14,"intelligence":6,"wisdom":13,"charisma":11,"baseatk":5,"cmb":6,"cmd":20,"feats":[{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":12},{"skill":"Knowledge (planes)","value":6},{"skill":"Perception","value":13},{"skill":"Stealth","value":12}],"languages":["Niln"],"sq":[{"type":"vapor form"}],"environments":["any (Quasi-Plane of Vapor)"],"organizations":["solitary","gang (2-4)"],"treasure":"none","description_visual":"A large amorphous cloud of nearly transparent vapor hovers. Small water droplets dance and play around the form and occasionally drop to the ground. Three large sapphire droplets centered on their form function as eyes. When manipulating objects or attacking, nilns form wispy and vaporous tendrils.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Drench","kind":"Ex","details":"The niln's touch puts out torches, campfires, exposed lanterns, and other open flames of nonmagical origin if these are of Large size or smaller. The creature can dispel magical fire as dispel magic (caster level equals the niln's HD)."},{"type":"Vapor Form","kind":"Su","details":"The niln spends the majority of its time in more or less solid form, but it can assume vapor form at will. It can switch forms once per round as a free action and can spend up to 20 rounds per day in vapor form. A niln in vapor form can fly at 60 ft. per round (perfect). This ability is otherwise similar to a gaseous form spell (caster level 5th)."}],"description":"Niln hail from a plane made of air and water; a vaporous and saturated realm known as the Quasi-Plane of Vapor. They are normally docile creatures, but are quick to anger, and relentless in their attack.\n\nLike many elementals, niln are most at home on their native plane and rarely leave it. They sometimes travel the Elemental Plane of Air when not traveling through their own realm, but usually don't enter other planes unless summoned. Should one find itself on the Material Plane, it seeks to escape and return to its home plane unless confined or summoned by a spellcaster. Assigned tasks are completed to the best of the niln's ability and they rarely ask for much of anything in return. On the Material Plane, a niln seeks sources of vapor or steam in which to bathe its form so they are almost always encountered in such areas.\n\nWhen first confronted, a niln surrounds itself with its drowning fog to deter would-be-aggressors. Those that insist on entering the fog and attacking the niln are met by its physical attack; the niln forms wispy tendrils from its form and lashes out at its foes. A niln will use its drench ability to extinguish any source of light its aggressors may be carrying, relying on its darkvision to aid it in the darkness thus created.","ecology":"","habitat_society":""},{"name":"Ommoth","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"magical beast","init":4,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"tremorsense","modifier":"120 ft."}],"ac":18,"ac_touch":9,"ac_flat_footed":18,"ac_mods":"+9 natural, -1 size","hp":59,"hd":"7d10+21","hdvalue":7,"fort":10,"ref":5,"will":2,"speed":[{"type":"land","speed":40}],"melee":"4 claws +13 (1d6+6 plus grab), 2 stings +13 (1d6+6 plus poison)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"constrict","details":"1d6+6"}],"strength":23,"dexterity":10,"constitution":16,"intelligence":2,"wisdom":10,"charisma":2,"baseatk":7,"cmb":14,"cmb_special":"+4 vs. grapple","cmd":24,"cmd_special":"+12 vs. trip","feats":[{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Climb","value":11},{"skill":"Perception","value":14},{"skill":"Stealth","value":5}],"environments":["any forests","any plains","temperate deserts","any underground","warm deserts"],"organizations":["solitary","pair","hunting band (3-6)"],"treasure":"incidental","description_visual":"This twelve-foot long creature resembles a giant scorpion with four menacing pincers and dual stingers.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Poison","kind":"Ex","details":"Sting-injury; save DC 18 Fort; frequency 1/round for 6 rounds; effect 1d4 Strength damage; cure 1 save. The save DC is Constitution-based and includes a +2 racial bonus."}],"description":"Ommoth are diurnal hunters that dine on giant insects and rodents; and the occasional adventurer that wanders too close to their nest. Hunting bands consist of both male and female ommoth with the strongest male being the leader of the pack. Favored prey of an ommoth includes large game, humanoids, and the occasional giant scorpion. Prey is always killed and carried back to the lair to be devoured or fed to the young. Young ommoth remain in the lair for three to six months generally, before dispersing into the world. A typical ommoth can live up to 30 years.\n\nAn ommoth lair is an underground burrow, either of their devising or an existing and abandoned burrow created by some other burrowing creatures. An existing burrow is often reconfigured to consist of a single long passageway that empties into a large main chamber. Here in the main chamber is the ommoth's nest. Any other passageways and chambers are sealed off by the ommoth with dirt, rocks, debris, and anything else it can find.\n\nAn ommoth is highly aggressive and attacks any creature that wanders into its territory. If cornered or threatened, it responds by rearing its claws and poising its tail overhead. Creatures that continue to harass the ommoth are met with a series of tail stings and claw attacks. An ommoth flees if confronted by a superior opponent, but if the nest is threatened, it fights to the death.\n\nAn ommoth appears as a twelve foot long giant scorpion with four large claws, two long tails that each end in a wicked stinger, and a carapace of reddish-brown or black. It has one set of eyes on the front of its head and two other pairs just behind those on the sides of its head. The creature has two sets of serrated mandibles that help in rending its food. Its forelegs are slightly longer and thinner than its others legs and it uses these to detect prey and explore its surroundings. Some species have white or tan markings on their undersides or white bands on their forelegs.","ecology":"","habitat_society":""},{"name":"Onyx Deer","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"magical beast","init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":17,"ac_touch":11,"ac_flat_footed":15,"ac_mods":"+2 Dex, +6 natural, -1 size","hp":59,"hd":"7d10+21","hdvalue":7,"fort":8,"ref":7,"will":3,"immunities":["petrification"],"speed":[{"type":"land","speed":40}],"melee":"gore +10 (1d8+4), 1 bite +10 (1d8+4), 2 hooves +5  (1d8+2)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"bellow"},{"type":"onyx bite"}],"strength":19,"dexterity":15,"constitution":17,"intelligence":5,"wisdom":12,"charisma":13,"baseatk":7,"cmb":12,"cmd":24,"cmd_special":"+4 vs. trip","feats":[{"feat":"Ability Focus (onyx bite)"},{"feat":"Improved Initiative"},{"feat":"Improved Natural Attack (hooves)"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":14}],"languages":["Sylvan (cannot speak)"],"environments":["temperate forests","warm forests"],"organizations":["solitary","band (2-5)","herd (6-18)"],"treasure":"none","description_visual":"This creature looks like a deer about 5 ft. tall at the shoulders with a dark brown head and chest changing to light brown on the rest of its body. A large white patch is prevalent across its back and rump. It has huge antlers at least as wide as a typical human is tall.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Bellow","kind":"Su","details":"Twice per day, an onyx deer can unleash a rumbling bellow that instills fear in any creature within 100 ft. that hears it. All creatures in the area must succeed on a DC 14 Will save or be shaken as long as they remain within the area and for 2d4 rounds afterward. A creature that succeeds on its saving throw is immune to the bellow of that onyx deer for 24 hours. The save DC is Charisma-based. Onyx deer are immune to their own bellow and that of other onyx deer."},{"type":"Onyx Bite","kind":"Su","details":"An onyx deer's bite deals 1d4 points of Constitution damage against a living creature if it fails a DC 18 Fortitude save. A living creature reduced to Constitution 3 or less transforms into onyx, resembling nothing more than a statue. A stone to flesh spell returns a transformed creature to its original form, though if it was reduced to Constitution 0 by the onyx deer's bite it immediately dies upon returning to its natural form. The save DC is Constitution-based."}],"description":"Other than being larger than most common deer, an onyx deer resembles its (thought to be distant) lesser cousin. These creatures are found in temperate and warm forested lands in the same general habitat as their normal counterparts though onyx deer don't associate with ordinary deer. Onyx deer are herd animals, congregating in groups of up to 20 individuals. Among the adults, the males outnumber the females by nearly a 2-to-1 ratio. Young (called does) make up the rest of the herd (their total number usually equals the number of adults in the herd).\n\nMating season for onyx deer comes in the fall. During this time males within the herd often clash with one another. Such clashes see the animals square off and charge headlong into each other crashing their antlers together and slashing with their sharp hooves. When one falls, the battle ends. The loser of the battle usually survives, but always leaves the herd.\n\nFemales give birth to 1d3 young in the early summer months.\n\nOnyx deer stand 5 to 6 ft. tall at the shoulder and weigh more than 800 pounds.\n\nOnyx deer are generally passive creatures and only attack when threatened or when their herd is threatened. If a herd is molested, both male and female onyx deer defend the young does to the death. An onyx deer begins combat by releasing a loud bellow in an attempt to scare off any would-be attackers. Those who stand their ground are met with either a gore attack and hooves or a ferocious bite and hooves. The bite of an onyx deer transforms the wound and flesh surrounding it into a gem-like stone that resembles onyx.","ecology":"","habitat_society":""},{"name":"River Troll","cr":5,"xp":1600,"alignment":"CE","size":"Large","type":"humanoid","subtypes":["amphibious","giant"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":16,"ac_touch":11,"ac_flat_footed":14,"ac_mods":"+2 Dex, +5 natural, -1 size","hp":63,"hd":"6d8+36","hdvalue":6,"hp_mods":["regeneration 5 (acid or fire)"],"fort":11,"ref":4,"will":3,"speed":[{"type":"land","speed":30},{"type":"swim","speed":40}],"melee":"bite +8 (1d8+5), 2 claws +8 (1d6+5)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rend","details":"2 claws, 1d6+7"}],"strength":21,"dexterity":14,"constitution":23,"intelligence":6,"wisdom":9,"charisma":6,"baseatk":4,"cmb":10,"cmd":22,"feats":[{"feat":"Intimidating Prowess"},{"feat":"Iron Will"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Intimidate","value":9},{"skill":"Perception","value":8},{"skill":"Swim","value":13}],"languages":["Giant"],"sq":[{"type":"amphibious"}],"environments":["temperate forests"],"organizations":["solitary","gang (3-6)"],"treasure":"standard","description_visual":"Similar in many respects to their swamp-loving kin, river trolls prefer a less slimy existence, and prefer to live in forested regions near rivers and streams, or under bridges.","group":"Troll","source":"Tome of Horrors 4 (3pp)","description":"River trolls patrol the banks of large rivers, looking to hunt the forest creatures that use the river for sustenance. Very rarely, the river trolls are indigent enough to use crude nets or spears to harvest fish and other aquatic foods from the river itself.\n\nRiver trolls are more frequently found as a group, as they are somewhat smaller than a normal troll (those only other trolls really notice this). They will work together with those of their own kind, but not with other common trolls.\n\nRiver trolls are adept swimmers, and like to lurk underwater for prey near bridges, if possible.","ecology":"","habitat_society":"","credit":"Originally appearing in Rappan Athuk Reloaded (© Necromancer Games, 2006)"},{"name":"Rope Golem","cr":5,"xp":1600,"alignment":"N","size":"Medium","type":"construct","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":17,"ac_touch":10,"ac_flat_footed":17,"ac_mods":"+7 natural","hp":53,"hd":"6d10+20","hdvalue":6,"fort":2,"ref":2,"will":2,"dr":"5/adamantine and slashing","immunities":["construct traits","magic"],"weaknesses":["vulnerability to fire"],"speed":[{"type":"land","speed":30}],"melee":"2 slams +9 (2d6+3 plus grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"strangulation","details":"1d8+3"}],"strength":17,"dexterity":10,"wisdom":11,"charisma":1,"baseatk":6,"cmb":9,"cmb_special":"+4 vs. grapple","cmd":19,"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"This construct is a tangled mess of knotted and bundled ropes in roughly humanoid form.","group":"Golem","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Strangulation","kind":"Ex","details":"A rope golem deals 1d8+3 points of damage with a successful grapple check. Because the rope golem seizes the opponent by the neck, a strangled foe cannot speak or cast spells with verbal components."},{"type":"Immunity to Magic","kind":"Ex","details":"A rope golem is immune to any spell or spell-like ability that allows spell resistance. In addition, certain spells and effects function differently against the creature, as noted below. A disintegrate spell affects it normally. A rope trick or animate rope spell deals 1d6 points of damage to the rope golem per three levels of the spell caster (e.g., a 6th-level sorcerer deals 2d6 points of damage to a rope golem if it casts rope trick or animate rope). A mending spell heals the rope golem of 2d6 points of damage. Fire-based effects and spells affect it as described in its fire vulnerability above."}],"description":"Rope golems are constructed from many intertwined and knotted ropes and often serve as guardians to lesser nobles, wizards, clerics, and the like, protecting a treasure hoard or some ancient knowledge best kept hidden. The typical rope golem stands 7 ft. tall but weighs only about 100 pounds or so. Its long, gangly arms end in noose-like hands. A rope golem can expand its shape to fill a 10-foot area or contract its form to fill a space less than 2 1/2 ft. square. Until it is activated, a rope golem appears to be nothing more than a pile of normal ropes. Rope golems cannot communicate. Rope golems attack by rolling their ropey appendages into \"fists\" and pummeling a foe. If a rope golem hits, it attempts to slip its noose-like hands over its opponent's head and around its neck. If successful, a rope golem often maintains the hold until it is destroyed or its opponent is dead. Construction A rope golem's body is spun and tied from 200 pounds of rope. Special bindings and powders worth 200 gp are used in the process. ROPE GOLEM CL 8th; Price 14,200 Requirements Craft Construct, animate rope, geas/quest, rope trick, creator must be caster level 8th; Skill Craft (ropemaking) DC 13; Cost 7,200.","ecology":"","habitat_society":""},{"name":"Scorpionfolk","cr":5,"xp":1600,"alignment":"LE","size":"Large","type":"monstrous humanoid","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":16,"ac_touch":10,"ac_flat_footed":15,"ac_mods":"+1 Dex, +6 natural, -1 size","hp":59,"hd":"7d10+21","hdvalue":7,"fort":5,"ref":6,"will":9,"defensive_abilities":["poison resistance"],"sr":16,"speed":[{"type":"land","speed":40}],"melee":"mwk falchion +11 (2d6+6), sting +5 (1d6+2 plus poison) or 2 claws +10 (1d6+4), sting +10 (1d6+2 plus poison)","ranged":"mwk composite shortbow +8 (1d8+4)","space":"10 ft.","reach":"5 ft.","strength":19,"dexterity":12,"constitution":16,"intelligence":8,"wisdom":14,"charisma":15,"baseatk":7,"cmb":12,"cmd":23,"cmd_special":"+12 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Cleave"},{"feat":"Iron Will"},{"feat":"Power Attack"}],"skills":[{"skill":"Climb","value":8},{"skill":"Diplomacy","value":6},{"skill":"Intimidate","value":9},{"skill":"Perception","value":14},{"skill":"Sense Motive","value":6},{"skill":"Stealth","value":4},{"skill":"Survival","value":9}],"languages":["Sadara"],"environments":["warm deserts"],"organizations":["solitary","gang (2-5)","band (6-10 plus 1-4 medium scorpions)","troop (11-20 plus 2-8 medium scorpions and 1 giant scorpion)","tribe (20-40 plus 8-16 medium scorpions and 2-4 giant scorpions)"],"treasure":"standard (masterwork falchion, masterwork composite shortbow, 30 arrows)","description_visual":"This creature has the upper torso of a muscular bronze-skinned humanoid and the lower torso of a giant sand-colored scorpion.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Poison","kind":"Ex","details":"Sting-injury; save DC 16 Fort; frequency 1/round; effect 1d2 Strength damage; cure 1 save. The save DC is Constitution-based."},{"type":"Poison Resistance","kind":"Ex","details":"Scorpionfolk gain a +4 racial bonus on all saving throws against poison."}],"description":"The people known as scorpionfolk (known as sadara among their own kind) are a race of nomadic desert-dwellers known for their cruelty and combat prowess. Believed to have once been a just and kind race that became corrupted by magic, scorpionfolk are feared and avoided by most intelligent desert-traveling races.\n\nMost scorpionfolk tribes tend to be nomadic and move around frequently, only settling in one place until the food source runs out. These tribes use tents for shelter and care little for any belongings other than what they can carry. Some few tribes settle in an area and construct small towns and villages of hardened mud, rock, and occasionally limestone. These tribes tend to be slightly more civilized than the nomadic scorpionfolk, and are often looked upon with disdain by their nomadic brothers. Larger tribes, both nomadic and settled, often have a shaman (a cleric or sorcerer of 5th-8th level) in their midst. These shamans tend to the sick and injured and sometimes take part in raids or excursions by the scorpionfolk. Tribal leaders are fighters or barbarians of 6th-9th level.\n\nScorpionfolk stand just over 6 ft. tall and are over 10 ft. long from head to the base of the tail. Tails range from 8 to 10 ft. long. Scorpionfolk, on average, weigh around 2,000 pounds. Their skin is usually bronze, brown, or black, and the lower scorpion torso dark tan or the color of dark sand. Hair color varies, with most males shaving their heads and females wearing their hair long in tightly knotted ponytails.\n\nScorpionfolk prefer to attack with weapons and a tail sting, only resorting to their clawed hands if necessary. Favored weapons of these creatures include falchions, spears, scimitars, and shortbows.","ecology":"","habitat_society":""},{"name":"Skin Stitcher","cr":5,"xp":1600,"alignment":"CE","size":"Medium","type":"aberration","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"skin scent"}],"ac":18,"ac_touch":12,"ac_flat_footed":16,"ac_mods":"+2 Dex, +6 natural","hp":45,"hd":"7d8+14","hdvalue":7,"fort":4,"ref":4,"will":6,"speed":[{"type":"land","speed":30}],"melee":"spiked chain +9 (2d4+4/x3) or 2 claws +8 (1d4+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"augmented critical"},{"type":"rage"}],"strength":16,"dexterity":14,"constitution":14,"intelligence":11,"wisdom":12,"charisma":6,"baseatk":5,"cmb":8,"cmd":20,"feats":[{"feat":"Blind-Fight"},{"feat":"Combat Reflexes"},{"feat":"Power Attack"},{"feat":"Weapon Focus (spiked chain)"}],"skills":[{"skill":"Climb","value":13},{"skill":"Intimidate","value":8},{"skill":"Perception","value":11},{"skill":"Stealth","value":12}],"environments":["any land","any underground"],"organizations":["solitary","gang (2-4)"],"treasure":"standard","description_visual":"This gaunt skeletal humanoid has heavily scarred flesh randomly stitched together. Its eyes are sunken and burn with hatred.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Augmented Critical","kind":"Ex","details":"If the skin stitcher scores a critical hit with a chain rake, it deals triple normal damage to an opponent."},{"type":"Rage","kind":"Ex","details":"A skin stitcher that takes damage in combat has a 50% chance of flying into a berserk rage the following round, attacking its foe until either it or its opponent is dead. It gains +4 Strength and -4 AC while raging. The skin stitcher cannot end its rage voluntarily. Note that the skin stitcher doesn't drop its chains while raging."},{"type":"Skin Scent","kind":"Ex","details":"The skin stitcher can detect any living creature that possesses natural skin to a distance of one-half mile. This includes all creature types, in most cases, except plants, elementals, oozes, constructs, vermin, and many undead (undead with flesh, such as zombies, can be detected by a skin stitcher, but skeletons cannot)."}],"description":"A skin stitcher is a malevolent and violent creature that kills for food, pleasure, and the skin of humanoids (which it keeps and collects). While it is known to eat just about anything it kills, it only keeps the skin and flesh of humanoid creatures. Other creatures are devoured, flesh and all.\n\nSkin stitchers collect the flesh and skin of any humanoid creature slain.\n\nFrom this, they weave intricate clothes and coverings that they wear over their entire body. At a distance, the skin stitcher can pass for a normal humanoid when wearing one of these \"skin suits\" (Perception check DC 20 to reveal its true identity). Up close, the skin stitcher's disguise becomes much less effective, making it appear as a humanoid with a heavily scarred and stitched together body.\n\nThe skin stitcher stands about 6 ft. tall and (in its true form) appears as a skinless humanoid. Its natural body appears to be bone wrapped tightly with corded muscle and covered with a dark red-purplish slime. Its eye sockets are deep and contain large bulbous eyes with blue irises. The skin stitcher's long, lanky arms end in claws as do its thick, muscled legs. It carries two large chains covered with many sharpened barbs.\n\nThough their hands are clawed, skin stitchers prefer to attack using large chains covered with razor-sharp barbs. These not only aid in killing a foe, but also help strip the flesh from a victim. Skin stitchers often attack from ambush, attempting to gain the upper hand over their prey as quickly as possible. Slain opponents are skinned and then eaten or carried to the skin stitcher's lair and devoured later.","ecology":"","habitat_society":"","gear":"spiked chain"},{"name":"Smilodon","cr":5,"xp":1600,"alignment":"N","size":"Medium","type":"animal","init":2,"senses":[{"type":"low-light vision"}],"ac":15,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+2 Dex, +3 natural","hp":51,"hd":"6d8+24","hdvalue":6,"fort":9,"ref":7,"will":3,"speed":[{"type":"land","speed":40}],"melee":"bite +10 (1d8+6 plus grab plus bleed), 2 claws +10  (1d4+6 plus grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bleed","details":"1d3"},{"type":"pounce"},{"type":"rake","details":"2 claws +10, 1d4+6"}],"strength":23,"dexterity":15,"constitution":19,"intelligence":2,"wisdom":12,"charisma":6,"baseatk":4,"cmb":10,"cmb_special":"+4 vs. grapple","cmd":22,"cmd_special":"+4 vs. trip","feats":[{"feat":"Power Attack"},{"feat":"Run"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Perception","value":9},{"skill":"Stealth","value":11,"special":"+15 in heavy undergrowth or tall grass"},{"skill":"Swim","value":10}],"environments":["warm forests","warm plains"],"organizations":["solitary","pair","den (6-10)"],"treasure":"none","description_visual":"This great cat is a terrifying apparition of power and violence, muscles rippling beneath its short fur and vicious saber-like teeth extending downward from its upper jaw.","source":"Tome of Horrors Complete (3pp)","description":"The smilodon, also known as the saber-toothed cat, is a powerful feline predator that savors the flesh of large creatures such as mastodons, mammoths, elephants, bison, buffalo, deer, and other great cats (excluding other smilodons). Smilodons are noted scavengers and have no problem devouring another animal's kill. Animals that resist the smilodon usually become part of the meal as well. Often mistakenly referred to as sabertoothed tigers by adventurers and sages, they are not in fact, related to tigers at all.\n\nBreeding season for smilodons takes place year round (that is, they have no set mating period). A male smilodon mates with all females in the den.\n\nGestation lasts about 80 days after which time 1d4+2 cubs are born. Cubs reach maturity around two years of age. Most leave the den and go on their own at this age.\n\nSmilodons average about five ft. long and weigh nearly 500 pounds, but can grow to a length of eight ft. and weigh up to 900 pounds. Their fur is golden or spotted (similar to a leopard). Their legs are short but powerful and their tail is short and bobbed. The smilodon has two eight-inch long, downward-curving canine teeth. These saber-like fangs are very sharp and are used for stabbing prey. This creature can open its jaws almost twice as far as other big cats. Other great cats, like lions and tigers, can only open their jaws to an angle of about 65-degrees, but the smilodon can stretch its jaws to an angle of 120-degrees.\n\nThese ferocious hunters prefer to attack from ambush, using their coloration to blend in with their surroundings so they can catch their opponents by surprise. When prey is spotted, the smilodon waits for it to come close, and then leaps to attack. When combating a foe, the sabertooth bites and rakes with its claws. It uses its long canine teeth to stab its prey, aiming for the fleshier and softer parts of its victim's body (such as the stomach or neck) where it inflicts terrible wounds with its saber-like teeth.","ecology":"","habitat_society":""},{"name":"Spitting Gargoyle","cr":5,"xp":1600,"alignment":"CE","size":"Medium","type":"monstrous humanoid","subtypes":["earth"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+2 Dex, +4 natural","hp":52,"hd":"5d10+20 (+5)","hdvalue":5,"fort":5,"ref":6,"will":4,"dr":"10/magic","speed":[{"type":"land","speed":40},{"type":"fly","speed":60,"maneuverability":"average"}],"melee":"2 claws +7 (1d6+2), bite +7 (1d4+2), gore +7 (1d4+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"acid spit"}],"strength":15,"dexterity":14,"constitution":18,"intelligence":10,"wisdom":11,"charisma":7,"baseatk":5,"cmb":7,"cmd":19,"feats":[{"feat":"Hover"},{"feat":"Skill Focus (Fly)"},{"feat":"Toughness"}],"skills":[{"skill":"Fly","value":13},{"skill":"Perception","value":10},{"skill":"Stealth","value":12,"special":"+16 stony environs"},{"skill":"Survival","value":8}],"languages":["Common","Terran"],"sq":[{"type":"freeze"}],"environments":["any"],"organizations":["solitary","pair","nasty (5-16)"],"treasure":"standard","description_visual":"A grotesque winged humanoid, it has a stony hide and wickedly-pointed horns. Its mouth is a gaping \"O\" like a waterspout, and its chin is stained with a green patina of corrosion.","group":"Gargoyle","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Acid Spit","kind":"Ex","details":"30-foot line, once every 4 rounds, damage 3d6 acid, Reflex DC 16 half. The save DC is Constitution based."},{"type":"Freeze","kind":"Ex","details":"A spitting gargoyle can hold itself so still it appears to be a statue. A spitting gargoyle that uses freeze can take 20 on its Stealth check to hide in plain sight as a stone statue."}],"description":"Like its cousin the common gargoyle, spitting gargoyles are cruel creatures taking great delight in torturing others just to watch their suffering. Before closing to attack with their melee attacks, spitting gargoyles often dive to use their acid spit attacks initially to soften up their targets. Other than the variations mentioned here, they in all other ways conform to a standard gargoyle.","ecology":"","habitat_society":"","credit":"Original author Greg A. Vaughan  Originally appearing in Slumbering Tsar (© Frog God Games/ Greg A. Vaughan, 2012)"},{"name":"Stegocentipede","cr":5,"xp":1600,"alignment":"N","size":"Huge","type":"vermin","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":10,"ac_flat_footed":15,"ac_mods":"+2 Dex, +7 natural, -2 size","hp":58,"hd":"9d8+18","hdvalue":9,"fort":8,"ref":5,"will":3,"defensive_abilities":["spines"],"immunities":["mind-affecting effects","vermin traits"],"speed":[{"type":"land","speed":40}],"melee":"bite +8 (2d6+4 plus poison), sting +8 (2d6+4 plus poison)","space":"15 ft.","reach":"15 ft.","strength":19,"dexterity":15,"constitution":14,"wisdom":10,"charisma":2,"baseatk":6,"cmb":12,"cmd":24,"cmd_special":"can't be tripped","skills":[{"skill":"Climb","value":8},{"skill":"Perception","value":4},{"skill":"Stealth","value":2}],"environments":["temperate forests"],"organizations":["solitary"],"treasure":"none","description_visual":"This creature resembles a gigantic centipede covered with chitinous plates of hardened bone that run along its back in double rows. Its rear portion ends in a long, scorpion-like stinger.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite or sting-injury; save Fort DC 18; frequency 1/round for 6 rounds; effect 1d6 Dex; cure 2 consecutive saves. The save DC is Constitution-based and includes a +2 racial bonus."},{"type":"Spines","kind":"Ex","details":"A stegocentipede raises its spine-plates during combat, and moves rapidly back and forth while attacking. Creatures in a space adjacent to a stegocentipede must succeed on a DC 16 Reflex save each time they attack it or take 2d8+2 points of damage from the spine-plates, whether the attack was successful or not. The save DC is Constitution-based."}],"description":"Stegocentipedes are rumored among sages to have come to the Material Plane from another plane or dimension, though no proof has been found to support this theory. Whatever their origin, they are greatly feared by adventurers and other dungeon dwelling denizens for their poisonous bite and sting.\n\nA stegocentipede raises its spines instinctively when it enters combat and rushes its prey. Opponents are bitten and stung to death.\n\nA typical stegocentipede is 18 ft. long. A stegocentipede ranges in color from brown to green.","ecology":"","habitat_society":"","credit":"The Stegocentipede originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Tazelwurm","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"magical beast","init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision","modifier":"null"},{"type":"scent"},{"type":"tremorsense","modifier":"60 ft."}],"ac":19,"ac_touch":11,"ac_flat_footed":17,"ac_mods":"+2 Dex, +8 natural, -1 size","hp":59,"hd":"7d10+21","hdvalue":7,"fort":8,"ref":7,"will":-2,"resists":[{"type":"fire","value":10}],"speed":[{"type":"land","speed":40}],"melee":"2 claws +10 (1d6+4), bite +11 (2d6+4)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"ambush"},{"type":"frightening exuviation"}],"strength":19,"dexterity":14,"constitution":16,"intelligence":2,"wisdom":15,"charisma":15,"baseatk":7,"cmb":5,"cmb_special":"+3 vs. grapple","cmd":9,"cmd_special":"can't be tripped","feats":[{"feat":"Improved Initiative"},{"feat":"Improved Natural Attack (bite)"},{"feat":"Power Attack"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Perception","value":8},{"skill":"Skill","value":13,"special":"+17 in rocky or subterranean environs"}],"environments":["any mountains"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"The emergent creature looks like a long serpent with grayish scales and a leonine head resembling female lion with grayish-tan fur. Two long, powerful humanoid arms protrude from its serpentine body, each ending in vicious-looking, slender talons.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Ambush","kind":"Ex","details":"If a tazelwurm catches an opponent flatfooted it gains a +4 circumstance bonus to its attack roll for that round."},{"type":"Frightening Exuviation","kind":"Ex","details":"If a tazelwurm is hit by a fire attack or effect that deals at least 10 points of damage, it takes no damage, but instead allows its scales, flesh, and fur to be consumed and burned away in a single round, exposing its skeletal structure. A creature viewing this must make a successful DC 15 Will save or paralyzed with fear for 1d3 rounds. The save DC is Charisma-based. A creature that successfully saves cannot be affected again by the same tazelwurm's frightening exuviation for one day. This has no effect on other tazelwurms."}],"description":"A tazelwurm is an aggressive, flesh-eating monster with a serpentine body, feline head, and two long powerful arms that end in razor-sharp claws. They haunt mountain passes and prey on travelers passing through their territory. Tazelwurms are masters of camouflage and are nearly indistinct from their rocky surroundings. They enjoy striking from ambush and downing unsuspecting prey. They are diurnal hunters and are most active in the morning hours. Their hunting grounds often cover several square miles of rocky terrain and should a tazelwurm enter another's territory, it is quickly driven away if detected. Tazelwurms eat just about anything that comes near, but they are especially fond of mountain lions and mountain goats. When the tazelwurm kills its prey, it drags it to its lair which takes the form of a well-hidden and nearly inaccessible depression or cave. The kill is devoured over a period of several days. Tazelwurms rarely interact with other creatures; including their own kind. When more than one is encountered, they are usually a mated pair. Young are born live and left to the care of the mother. Young tazelwurms reach maturity around two years of age and leave the lair to go out on their own. Very old tazelwurms may even have lichens and mosses growing on them, enhancing their rocky appearances. A tazelwurm lies in wait for its meals. Using its tremorsense ability, it senses vibrations in the rocks where it hides and springs to attack when prey draws near. Tazelwurms generally avoid large groups of travelers, preferring to attack a straggler or a member of a party that happens to have gotten lost or separated. A hungry tazelwurm though, will attack just about anything that comes near it.","ecology":"","habitat_society":""},{"name":"Thunder Beast","cr":5,"xp":1600,"alignment":"N","size":"Huge","type":"magical beast","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":14,"ac_touch":8,"ac_flat_footed":14,"ac_mods":"+6 natural, -2 size","hp":69,"hd":"6d10+36","hdvalue":6,"fort":10,"ref":5,"will":12,"speed":[{"type":"land","speed":30}],"melee":"bite +14 (2d6+15)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"breath weapon","details":"20 ft. cone, sickened, Fort DC 18 resists"},{"type":"trample","details":"2d6+15, DC 23"}],"strength":30,"dexterity":10,"constitution":21,"intelligence":2,"wisdom":13,"charisma":7,"baseatk":6,"cmb":49,"cmb_special":"+4 vs. bull rush, grapple, overrun, or sunder","cmd":57,"cmd_special":"+2 vs. bull rush, overrun, or sunder, +4 vs. trip","feats":[{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Vital Strike"}],"skills":[{"skill":"Perception","value":13}],"environments":["any Abyss"],"organizations":["herd (5-20; 50% noncombatant young)"],"treasure":"none","description_visual":"This huge beast has a hippo-like head with pointed pig-like ears. It has a large, wide mouth with small upright tusks jutting from its lower jaw.  Its long body is thick and hunched. Six powerful legs aid the creature in locomotion.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Breath Weapon","kind":"Ex","details":"Every 1d4 rounds as a swift action, a thunder beast can exhale a cloud of poisonous gas in a 20- foot cone. Living creatures in the area must succeed on a DC 18 Fortitude save or sickened every round they remain in the area and for one round after leaving the area. The save DC is Constitution-based. The cloud lasts 1d4 rounds before dispersing. A strong wind (21+ mph) disperses the cloud in 1 round."}],"description":"Thunder beasts are herd animals that spend their time roaming the uncountable layers of the Abyss sustaining themselves on a diet of rotted plants, minor demons, and other inconsequential life forms.\n\nIf angry or frightened, a thunder beast bellows with a low, rumbling tone. If the object of their concern doesn't immediately withdraw, they then breathe their foul breath and attack with their vicious bite.\n\nA typical thunder beast is about 20 ft. long. It is yellow-brown, ochre, or olive in color, mottled dark brown or black.","ecology":"","habitat_society":"","credit":"The Thunder Beast originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Transposer","cr":5,"xp":1600,"alignment":"N","size":"Medium","type":"aberration","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":14,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+1 Dex, +1 dodge, +2 natural","hp":33,"hd":"6d8+6","hdvalue":6,"fort":3,"ref":3,"will":10,"defensive_abilities":["transposition"],"speed":[{"type":"land","speed":30}],"melee":"2 slams +5 (1d6+1 plus transposition)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"transposition"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"disguise self"}]}],"strength":12,"dexterity":13,"constitution":12,"intelligence":8,"wisdom":12,"charisma":12,"baseatk":4,"cmb":21,"cmd":32,"cmd_special":"can't be tripped","feats":[{"feat":"Dodge"},{"feat":"Skill Focus (Disguise)"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Bluff","value":7},{"skill":"Disguise","value":10,"special":"+13 when using disguise self"},{"skill":"Perception","value":13}],"languages":["Aklo","Common"],"sq":[{"type":"blending disguise"}],"environments":["any"],"organizations":["solitary"],"treasure":"standard","description_visual":"This creature looks like a featureless humanoid whose arms end in large sucker-like membranes.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Blending Disguise","kind":"Ex","details":"When using its disguise self spell-like ability, the transposer can make itself look like a creature of the humanoid or monstrous humanoid type. When disguising itself, the transposer ignores the usual penalty for different race, age category, and gender. Finally, transposers gain a racial bonus equal to one half their racial Hit Dice to the Will save DC to penetrate the illusion of their disguise self ability."},{"type":"Transposition","kind":"Su","details":"An opponent hit by a transposer's slam attack becomes linked (transposed) to it by an invisible and undetectable field of energy for 1 hour if it fails a DC 14 Fortitude save. A transposer can have a number of opponents equal to its HD linked to it at one time. An opponent can be linked to more than one transposer (if it fails its save against each transposer's attack). The save DC is Constitution-based. When a linked opponent attacks a transposer it is linked to, the creature gains hit points equal to the damage the attack would normally deal, and the attacker takes the damage. Other opponents linked to that transposer are unharmed. A transposer can gain up to the maximum hit points allowed by its Hit Dice. It cannot gain bonus or temporary hit points from this ability. Curative magic cast on a transposer by a transposed opponent damages the creature by the amount it would normally heal, and heals a like amount of damage on the one who cast the spell. (Other linked creatures are unaffected.) Curative magic cast on a transposed opponent works normally but doesn't heal or harm a linked transposer. Curative magic cast on a transposer by a non-linked opponent functions normally. Opponents not linked to the transposer can attack and affect the creature normally."}],"description":"Transposers are thought to be of an alien culture; how they came to the Material Plane remains a mystery to sages. Most transposers avoid contact with sentient races, preferring to live in seclusion among their own kind. When it first encounters potential prey, a transposer uses its change self ability to lure its target into range. It usually takes the shape of a creature of the same race as its potential prey if possible. Once its prey is in range, the transposer lashes out with its arms. Once it transposes a target, it pummels it relentlessly with its arms.","ecology":"","habitat_society":"","credit":"The Transposer originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Vegepygmy Subchief","cr":5,"xp":1600,"alignment":"N","size":"Medium","type":"plant","subtypes":["fungus"],"init":1,"senses":[{"type":"low-light vision"}],"ac":16,"ac_touch":11,"ac_flat_footed":15,"ac_mods":"+1 Dex, +5 natural","hp":51,"hd":"6d8+24","hdvalue":6,"fort":8,"ref":3,"will":3,"dr":"5/bludgeoning or slashing","immunities":["electricity","plant traits"],"speed":[{"type":"land","speed":30}],"melee":"2 claws +8 (1d4+4) or spear +9 (1d8+6 /x3)","ranged":"spear +6 (1d8+4/x3)","space":"5 ft.","reach":"5 ft.","strength":19,"dexterity":12,"constitution":17,"intelligence":10,"wisdom":13,"charisma":12,"baseatk":4,"cmb":8,"cmd":19,"feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"},{"feat":"Weapon Focus (spear)"}],"skills":[{"skill":"Perception","value":13},{"skill":"Stealth","value":14,"special":"+22 in forested or swampy areas"}],"environments":["any underground"],"organizations":["solitary","gang (1 plus 2-4 bodyguards)","band (1 plus 2-4 bodyguards, 2-5 guards, 4-7 workers and 6-11 commoners)","war band (1 plus 2-8 bodyguards, 6-11 guards, 20-40 workers, 1-4 thornies)"],"treasure":"standard","description_visual":"This creature resembles a humanoid with green vegetable-like skin and razor-sharp claws. Its head sports two large yellow eyes, a wide mouth, inset nose, and a topknot of dark brown leaves. Leafy tendrils protrude from its shoulders, midsection, arms, and legs.","group":"Vegepygmy","source":"Tome of Horrors Complete (3pp)","description":"When a living creature is slain by russet mold (see that entry), it rises as a vegepygmy commoner. Vegepygmies are low-intelligence plants that make their home deep in the forests or underground away from most settled areas. They are hunters and scavengers, and carnivorous, preying on living creatures weaker than themselves. A vegepygmy ranges from two ft. to four and a half ft. tall. Though they don't seem to have ears, it is well known that vegepygmies can hear. Vegepygmies don't speak, but communicate with others of their kind by thumping their chest or rapping their spears on rocks, earth, or some other solid surface. It isn't known if or how they communicate with other creatures. Vegepygmies attack with claws or weapons, usually either a longspear or club. They prefer to ambush opponents, using their coloration to blend with their natural surroundings.","ecology":"","habitat_society":"","credit":"The Vegepygmy originally appeared in the First Edition module S3 Expedition to the Barrier Peaks (© TSR/Wizards of the Coast, 1980) and later in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission.","gear":"spear"},{"name":"Wind Walker","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"outsider","subtypes":["air","elemental","extraplanar"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+4 Dex, +4 natural, -1 size","hp":59,"hd":"7d10+21","hdvalue":7,"fort":4,"ref":9,"will":6,"dr":"5/magic","immunities":["magic","elemental traits"],"speed":[{"type":"land","speed":40},{"type":"fly","speed":60,"maneuverability":"perfect"}],"melee":"wind blast +10 (2d6+6)","space":"10 ft.","reach":"10 ft.","spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect thoughts","details":"100 ft."}]}],"strength":18,"dexterity":19,"constitution":14,"intelligence":12,"wisdom":13,"charisma":11,"baseatk":7,"cmb":12,"cmd":26,"feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":6},{"skill":"Diplomacy","value":10},{"skill":"Fly","value":20},{"skill":"Intimidate","value":10},{"skill":"Knowledge (planes)","value":11},{"skill":"Perception","value":11},{"skill":"Sense Motive","value":8},{"skill":"Stealth","value":10}],"languages":["Auran","Common","telepathy 100 ft."],"environments":["any (Elemental Plane of Air)"],"organizations":["solitary","gang (2-4)"],"treasure":"standard","description_visual":"A roaring cyclone at least twice as tall as a human bears down on you, spinning dirt and earth into the air as it moves.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Detect Thoughts","kind":"Sp","details":"For every wind walker present within 100 ft., the range of this spell-like ability increases by 100 ft."},{"type":"Immunity to Magic","kind":"Ex","details":"A wind walker is immune to any spell or spell-like ability that allows spell resistance (except those that summon or call it). In addition, certain spells and effects function differently against the creature as noted below. A control weather spell instantly slays a wind walker if it fails a Fortitude save against the spell. A haste spell deals 1d6 points of damage per two caster levels (maximum 5d6) to a wind walker. A Fortitude save halves the damage. In addition, a haste spell increases the damage the wind walker deals with its wind blast attack by +1d6 for one round. An ice storm spell deals no damage to a wind walker, but is affected as if by a fear spell if it fails a Will saving throw against ice storm. A slow spell deals 1d6 points of damage per caster level (maximum 10d6) to a wind walker. A Will save halves the damage. A summoned or called wind walker is affected normally by magical barriers that restrict or inhibit called or summoned creatures (such as antimagic field)."},{"type":"Wind Blast","kind":"Ex","details":"A wind walker attacks using the air surrounding it, transforming it into a forceful blast that deals 2d6+6 points of damage to all creatures within reach. The wind walker makes a single attack roll at its full attack bonus against each opponent within reach as a standard action."}],"description":"Wind walkers are creatures from the Plane of Air. They are often summoned to the material plane by clerics or wizards who employ them as guards. On occasion, a wind walker is encountered in the service of a cloud giant, djinn, efreet, storm giant, or other such creature.\n\nA wind walker's natural form is that of a roaring and whistling column of wind about 12 ft. tall. No discernable features can be seen in the wind walker.\n\nA wind walker attacks by using the surrounding air to pummel its foes.","ecology":"","habitat_society":"","credit":"The Wind Walker originally appeared in the First Edition Monster Manual (© TSR/Wizards of the Coast, 1977) and is used by permission."},{"name":"Wood Giant","cr":5,"xp":1600,"alignment":"CG","size":"Large","type":"humanoid","subtypes":["giant"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":18,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+2 armor, +3 Dex, +4 natural, -1 size","hp":52,"hd":"7d8+21","hdvalue":7,"fort":8,"ref":5,"will":7,"save_mods":"+2 vs. enchantment","speed":[{"type":"land","speed":40}],"melee":"greatsword +9 (3d6+7/19-20)","ranged":"mwk composite longbow (+5 Str) +9 (2d6+5/x3)","space":"10 ft.","reach":"10 ft.","strength":21,"dexterity":16,"constitution":17,"intelligence":14,"wisdom":14,"charisma":12,"baseatk":5,"cmb":12,"cmd":27,"feats":[{"feat":"Deadly Aim"},{"feat":"Point Blank Shot"},{"feat":"Martial Weapon Proficiency (longbow)"},{"feat":"Weapon Focus (longbow)"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Climb","value":15},{"skill":"Perception","value":9},{"skill":"Stealth","value":6,"special":"+10 in forests"}],"languages":["Common","Giant","Sylvan"],"sq":[{"type":"change shape 3/day","details":"alter self, giant form I"}],"environments":["temperate forests","warm forests"],"organizations":["solitary","gang (2-5)","clan (6-9 plus 35% noncombatants)","trading party (2-5 plus 2-4 wood elves)","hunting party (2-5 plus 2-4 wood elves and 1-4 dire wolves)"],"treasure":"standard","description_visual":"This giant resembles a wood elf of about 10 ft. tall. It has brownish-green skin, a bald head, and bright green eyes.","group":"Giant","source":"Tome of Horrors Complete (3pp)","description":"Wood giants are peaceful, good-natured giants found in the forested areas of the world. The average wood giant stands 9 ft. tall, weighs 900 pounds, and resembles a large wood elf. Wood giants have large heads and prominent jaws; their elf-like ears sit high on their long, oval heads. Most wood giants (particularly males) are bald. Their skin is usually brownish-green. Wood giants dress in greens or browns and prefer neutral colors to the bright or dull colors of other races. Wood giants can live to be 400 years old. Wood giants are on friendly terms with most benign creatures of the forest, particularly wood elves. Though contact outside their immediate clan is rare, they do occasionally have dealings with nearby tribes of wood elves. Wood giant villages are large and open expanses of land with few if any buildings or shelters. Wood giants prefer to spend their time under the warmth of the day and the serenity of the night. They don't associate with-and usually attack on sight-evil forest creatures. Wood giants usually attack from ambush, hiding in dense undergrowth and firing at their prey with their bows before closing to melee with their greatswords.","as_character":[{"description":"Most wood giant chieftains are rangers. Wood giant clerics are called shamans and can choose two of the following domains Animal, Earth, or Plant. Wood giant characters possess the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+10 Str, +6 Dex, +6 Con, +4 Int, +4 Wis, +2 Cha: Wood giants are powerful and clever forest-dwellers."},{"type":"Large size","value":"-1 penalty to Armor Class, -1 penalty on attack rolls, -4 penalty on Stealth checks, +1 bonus to CMB and CMD, lifting and carrying limits double those of Medium characters."},{"type":"Low-Light Vision","value":"Wood giants can see twice as far as humans in conditions of dim light."},{"type":"Darkvision","value":"Wood giants can see in the dark to a range of 60 ft."},{"type":"Saves","value":"Wood giants have a +2 bonus to saves vs. spells of the enchantment school."},{"type":"Armor","value":"Wood giants have a +4 natural armor bonus."},{"type":"Speed","value":"40 ft."},{"type":"Racial Hit Dice","value":"A wood giant begins with seven levels of giant, which provide 7d8 Hit Dice, a base attack bonus of +5, and base saving throw bonuses of Fort +5, Ref +2, and Will +2."},{"type":"Racial Skills","value":"A wood giant's giant humanoid levels give it skill ranks equal to 7 x (2 + Int modifier). A wood giant has a +4 racial bonus on Stealth checks in forested areas."},{"type":"Racial Feats","value":"A wood giant's giant levels give it three feats."},{"type":"Special Qualities","value":"Change shape"},{"type":"Automatic Languages","value":"Giant."},{"type":"Bonus Languages","value":"Common, Draconic, Elven, Goblin, Orc, and Sylvan."}]}],"ecology":"","habitat_society":"","credit":"The Wood Giant originally appeared in the Second Edition Monstrous Compendium 5 (© TSR/Wizards of the Coast, 1990) and is used by permission.","gear":"greatsword, masterwork composite longbow (+5 Str), 20 arrows, leather armor"}];
